"""Rigidity audit: numerical verification of the three structure theorems for
maximisers of the semiprime OR dial.

For each modulus the script
  (1) locates the true maximum over all 0/1 profiles by exhaustive enumeration;
  (2) checks the FIRST rigidity theorem: at the maximum the mean no-fork rate is
      exactly 1/2, i.e. P(OR) = 3/4;
  (3) checks the SECOND rigidity theorem: the conditional no-fork probabilities
      take only the values 0 and 1/2;
  (4) checks the THIRD rigidity theorem plus the classification: the maximiser is
      0/1-valued and its support is a coset of an index-two subgroup, equivalently
      a fibre of a quadratic character;
  (5) exhibits the strict loss suffered by perturbing a maximiser: moving a single
      class rate away from 0/1 lowers the dial immediately.
"""

from __future__ import annotations

import itertools
import math
from typing import Dict, List, Sequence, Tuple


def binary_entropy_bits(x: float) -> float:
    if x <= 0.0 or x >= 1.0:
        return 0.0
    return -x * math.log2(x) - (1.0 - x) * math.log2(1.0 - x)


CAP: float = binary_entropy_bits(0.75) - 0.5 * binary_entropy_bits(0.5)


def units(m: int) -> List[int]:
    return [a for a in range(1, m) if math.gcd(a, m) == 1]


def no_fork(m: int, s: Dict[int, float]) -> Dict[int, float]:
    us = sorted(s)
    inv = {a: pow(a, -1, m) for a in us}
    return {c: sum(s[a] * s[(c * inv[a]) % m] for a in us) / len(us) for c in us}


def dial_bits(m: int, s: Dict[int, float]) -> float:
    us = sorted(s)
    mu = sum(s.values()) / len(us)
    f = no_fork(m, s)
    return (binary_entropy_bits(mu * mu)
            - sum(binary_entropy_bits(f[c]) for c in us) / len(us))


def is_subgroup(m: int, support: Sequence[int]) -> bool:
    ss = set(support)
    return 1 in ss and all((a * b) % m in ss for a in ss for b in ss)


def best_profile(m: int) -> Tuple[float, Dict[int, float]]:
    us = units(m)
    best, arg = -1.0, {}
    for bits in itertools.product((0.0, 1.0), repeat=len(us)):
        s = {a: bits[i] for i, a in enumerate(us)}
        value = dial_bits(m, s)
        if value > best:
            best, arg = value, s
    return best, arg


def cyclic_dial_bits(n: int, s: List[float]) -> float:
    """Dial of a no-fork profile on the additive cyclic class group Z/n."""
    mu = sum(s) / n
    f = [sum(s[a] * s[(c - a) % n] for a in range(n)) / n for c in range(n)]
    return (binary_entropy_bits(mu * mu)
            - sum(binary_entropy_bits(x) for x in f) / n)


def best_cyclic_profile(n: int) -> float:
    """Maximum of the dial over all 0/1 profiles on Z/n."""
    return max(cyclic_dial_bits(n, list(bits))
               for bits in itertools.product((0.0, 1.0), repeat=n))


def audit(m: int) -> None:
    us = units(m)
    value, s = best_profile(m)
    mu = sum(s.values()) / len(us)
    f = no_fork(m, s)
    support = tuple(a for a in us if s[a] == 1.0)
    x_inv = pow(support[0], -1, m)
    translate = sorted((x_inv * a) % m for a in support)

    print(f"--- m = {m}  (class group of order {len(us)}) ---")
    print(f"  maximum found            : {value:.9f} bits "
          f"({'equals g(2)' if abs(value - CAP) < 1e-9 else 'NOT the cap'})")
    print(f"  [R1] mean no-fork rate mu: {mu:.6f}   P(OR) = {1 - mu * mu:.6f}")
    vals = sorted({round(f[c], 9) for c in us})
    print(f"  [R2] values of f(c)      : {vals}")
    print(f"  [R3] profile 0/1-valued  : "
          f"{all(v in (0.0, 1.0) for v in s.values())}")
    print(f"  classification           : support {support} is a coset of the "
          f"index-two subgroup {tuple(translate)}: "
          f"{is_subgroup(m, translate) and 2 * len(support) == len(us)}")

    # perturb one coordinate away from the vertex
    print("  perturbation of a single class rate:")
    a0 = support[0]
    for eps in (0.05, 0.15, 0.30, 0.50):
        t = dict(s)
        t[a0] = 1.0 - eps
        print(f"      s({a0}) = {t[a0]:.2f}  ->  Phi = {dial_bits(m, t):.9f} bits "
              f"(loss {value - dial_bits(m, t):.9f})")
    print()


def main() -> None:
    print(f"cap g(2) = H(3/4) - H(1/2)/2 = {CAP:.9f} bits\n")
    for m in (5, 8, 11, 16):
        audit(m)
    print("An odd-order class group carries no quadratic character, so the cap is")
    print("unattainable there.  Unit groups modulo m are always of even order for")
    print("m > 2, so we exhibit the obstruction on abstract cyclic class groups")
    print("Z/n with n odd (these arise as quotients, e.g. the cubic residue group):")
    for n in (3, 5, 9):
        value = best_cyclic_profile(n)
        print(f"   G = Z/{n} (|G| = {n}, odd): max = {value:.9f} < {CAP:.9f}")
    for n in (4, 6):
        value = best_cyclic_profile(n)
        print(f"   G = Z/{n} (|G| = {n}, even): max = {value:.9f} "
              f"({'= g(2)' if abs(value - CAP) < 1e-9 else 'below the cap'})")


if __name__ == "__main__":
    main()

