"""Algorithm 1: exact evaluation of the semiprime OR dial by group convolution.

Given a modulus m and a class-rate profile r on (Z/m)^x, compute

    s(a)   = 1 - r(a)                         (no-fork profile)
    mu     = avg_a s(a)
    f(c)   = avg_a s(a) s(c a^{-1})           (group convolution)
    Phi    = H(mu^2) - avg_c H(f(c))          (mutual information, in bits)

Complexity: O(phi(m)^2) arithmetic operations after an O(phi(m)^2) precomputation
of the inverse table (or O(phi(m) log m) with modular inversion).
"""

from __future__ import annotations

import math
from typing import Dict, List, Sequence


def binary_entropy_bits(x: float) -> float:
    """H(x) = -x log2 x - (1-x) log2 (1-x), with H(0) = H(1) = 0."""
    if x <= 0.0 or x >= 1.0:
        return 0.0
    return -x * math.log2(x) - (1.0 - x) * math.log2(1.0 - x)


def units(m: int) -> List[int]:
    """The class group (Z/m)^x, as a sorted list of representatives."""
    return [a for a in range(1, m) if math.gcd(a, m) == 1]


def inverse_table(m: int, us: Sequence[int]) -> Dict[int, int]:
    """Multiplicative inverses of all units modulo m."""
    return {a: pow(a, -1, m) for a in us}


def conditional_no_fork(m: int, s: Dict[int, float]) -> Dict[int, float]:
    """f(c) = avg_a s(a) s(c a^{-1}) for every class c."""
    us = sorted(s)
    inv = inverse_table(m, us)
    phi = len(us)
    return {c: sum(s[a] * s[(c * inv[a]) % m] for a in us) / phi for c in us}


def or_dial_bits(m: int, rate: Dict[int, float]) -> float:
    """The OR-channel mutual information I(N mod m ; [E(p) or E(q)]), in bits."""
    us = sorted(rate)
    s = {a: 1.0 - rate[a] for a in us}
    mu = sum(s.values()) / len(us)
    f = conditional_no_fork(m, s)
    conditional = sum(binary_entropy_bits(f[c]) for c in us) / len(us)
    return binary_entropy_bits(mu * mu) - conditional


def or_cap_bits() -> float:
    """g(2) = H(3/4) - H(1/2)/2 = 0.311278... bits."""
    return binary_entropy_bits(0.75) - 0.5 * binary_entropy_bits(0.5)


if __name__ == "__main__":
    m = 11
    squares = {(a * a) % m for a in units(m)}
    legendre = {a: (1.0 if a in squares else 0.0) for a in units(m)}
    print(f"Legendre kernel mod {m}: Phi = {or_dial_bits(m, legendre):.9f} bits")
    print(f"cap                    : g(2) = {or_cap_bits():.9f} bits")

"""Algorithm 2: exhaustive search for the maximiser of the OR dial, with structural
certification of the argmax.

The rigidity theorem "a maximiser is 0/1-valued" reduces the continuous
optimisation over the cube [0,1]^phi to a search over the 2^phi vertices.  This
algorithm enumerates all vertices, records the maximum, and then certifies that
each maximiser is the indicator of a coset of an index-two subgroup (equivalently
the +1 or -1 fibre of a quadratic character).

Complexity: O(2^phi * phi^2) for the enumeration; the certification of a single
argmax costs O(phi^2).  Practical for phi <= 16, which covers all moduli up to
m = 60 or so.
"""

from __future__ import annotations

import itertools
import math
from typing import Dict, List, Sequence, Tuple


def binary_entropy_bits(x: float) -> float:
    if x <= 0.0 or x >= 1.0:
        return 0.0
    return -x * math.log2(x) - (1.0 - x) * math.log2(1.0 - x)


def units(m: int) -> List[int]:
    return [a for a in range(1, m) if math.gcd(a, m) == 1]


def or_dial_bits(m: int, s: Dict[int, float]) -> float:
    """Dial of a *no-fork* profile s, in bits."""
    us = sorted(s)
    inv = {a: pow(a, -1, m) for a in us}
    phi = len(us)
    mu = sum(s.values()) / phi
    f = {c: sum(s[a] * s[(c * inv[a]) % m] for a in us) / phi for c in us}
    return (binary_entropy_bits(mu * mu)
            - sum(binary_entropy_bits(f[c]) for c in us) / phi)


def is_subgroup(m: int, support: Sequence[int]) -> bool:
    """Closure test: is `support` a subgroup of (Z/m)^x?"""
    ss = set(support)
    return 1 in ss and all((a * b) % m in ss for a in ss for b in ss)


def is_index_two_coset(m: int, support: Sequence[int]) -> bool:
    """Is `support` a coset of an index-two subgroup of (Z/m)^x?"""
    us = units(m)
    if 2 * len(support) != len(us):
        return False
    x_inv = pow(support[0], -1, m)
    translate = sorted((x_inv * a) % m for a in support)
    return is_subgroup(m, translate)


def maximise(m: int) -> Tuple[float, List[Tuple[int, ...]], bool]:
    """Return (max dial, list of argmax supports, all-argmax-are-cosets flag)."""
    us = units(m)
    best, argmax = -1.0, []
    for bits in itertools.product((0.0, 1.0), repeat=len(us)):
        s = {a: bits[i] for i, a in enumerate(us)}
        value = or_dial_bits(m, s)
        if value > best + 1e-12:
            best, argmax = value, [tuple(a for i, a in enumerate(us) if bits[i])]
        elif abs(value - best) <= 1e-12:
            argmax.append(tuple(a for i, a in enumerate(us) if bits[i]))
    certified = all(is_index_two_coset(m, A) for A in argmax if A)
    return best, argmax, certified


if __name__ == "__main__":
    cap = binary_entropy_bits(0.75) - 0.5 * binary_entropy_bits(0.5)
    for m in (3, 4, 5, 7, 8, 9, 11, 16, 21):
        best, argmax, certified = maximise(m)
        print(f"m = {m:>2}: max = {best:.9f} bits "
              f"({'= g(2)' if abs(best - cap) < 1e-9 else 'DIFFERENT'}), "
              f"{len(argmax)} maximisers, all index-two cosets: {certified}")

"""Algorithm 3: the multi-prime dial by iterated convolution, and the decay ladder.

For N = p_1 ... p_k with independent uniform classes, the conditional no-fork
probability is the k-fold group convolution s^{*k}, whose average is mu^k and
which is bounded pointwise by mu^{k-1}.  The dial is

    Phi_k = H(mu^k) - avg_c H(s^{*k}(c)).

This routine computes Phi_k for any profile, and compares it with the exact
closed form along subgroup kernels,

    Phi_k(1_K) = H(d^{-k}) - (1/d) H(d^{-(k-1)}),   d = [G : K].

Complexity: O(k * phi^2).  The theory guarantees Phi_k <= 0.311278 bits for all
k >= 2, with a uniform margin for k >= 3.
"""

from __future__ import annotations

import math
from typing import Dict, List


def binary_entropy_bits(x: float) -> float:
    if x <= 0.0 or x >= 1.0:
        return 0.0
    return -x * math.log2(x) - (1.0 - x) * math.log2(1.0 - x)


def units(m: int) -> List[int]:
    return [a for a in range(1, m) if math.gcd(a, m) == 1]


def convolve(m: int, t: Dict[int, float], s: Dict[int, float]) -> Dict[int, float]:
    """(t * s)(c) = avg_a t(a) s(c a^{-1})."""
    us = sorted(s)
    inv = {a: pow(a, -1, m) for a in us}
    return {c: sum(t[a] * s[(c * inv[a]) % m] for a in us) / len(us) for c in us}


def multi_dial_bits(m: int, rate: Dict[int, float], k: int) -> float:
    """Phi_k for a fork-rate profile and k prime factors, in bits."""
    us = sorted(rate)
    s = {a: 1.0 - rate[a] for a in us}
    mu = sum(s.values()) / len(us)
    power = dict(s)
    for _ in range(k - 1):
        power = convolve(m, power, s)
    conditional = sum(binary_entropy_bits(power[c]) for c in us) / len(us)
    return binary_entropy_bits(mu ** k) - conditional


def kernel_closed_form(index: int, k: int) -> float:
    """Exact value H(d^-k) - (1/d) H(d^-(k-1)) for an index-d kernel."""
    d = float(index)
    return (binary_entropy_bits(d ** -k)
            - binary_entropy_bits(d ** (-(k - 1))) / d)


if __name__ == "__main__":
    cap = binary_entropy_bits(0.75) - 0.5 * binary_entropy_bits(0.5)
    m = 13
    squares = {(a * a) % m for a in units(m)}
    # fork event = "p is a quadratic residue mod 13"; complement gives the same dial
    rate = {a: (0.0 if a in squares else 1.0) for a in units(m)}
    print(f"cap g(2) = {cap:.9f} bits")
    for k in range(2, 8):
        measured = multi_dial_bits(m, rate, k)
        exact = kernel_closed_form(2, k)
        print(f"k = {k}: measured {measured:.9f}   closed form {exact:.9f}   "
              f"margin to cap {cap - measured:.9f}")
